const markdown = $('Proposal Revision Agent').isExecuted
  ? $('Proposal Revision Agent').last().json.output
  : $('Proposal Writer').item.json.output;

const docJson = $json.body || {};
const docContent = docJson.content || [];
const endIndex = docContent.length ? docContent[docContent.length - 1].endIndex : 1;

// ---------- Inline parser (bold / italic / inline code) ----------
function parseInline(raw) {
  let text = '';
  const bolds = [];
  const italics = [];
  const codes = [];
  let i = 0;
  const n = raw.length;
  while (i < n) {
    if (raw[i] === '`') {
      const end = raw.indexOf('`', i + 1);
      if (end !== -1) {
        const inner = raw.slice(i + 1, end);
        const start = text.length;
        text += inner;
        codes.push([start, text.length]);
        i = end + 1;
        continue;
      }
    }
    if (raw.slice(i, i + 2) === '**' || raw.slice(i, i + 2) === '__') {
      const marker = raw.slice(i, i + 2);
      const end = raw.indexOf(marker, i + 2);
      if (end !== -1) {
        const inner = raw.slice(i + 2, end);
        const start = text.length;
        const p = parseInline(inner);
        text += p.text;
        bolds.push([start, text.length]);
        for (const [s, e] of p.italics) italics.push([s + start, e + start]);
        for (const [s, e] of p.codes) codes.push([s + start, e + start]);
        i = end + 2;
        continue;
      }
    }
    if (raw[i] === '*' || raw[i] === '_') {
      const marker = raw[i];
      const end = raw.indexOf(marker, i + 1);
      if (end !== -1 && end > i + 1) {
        const inner = raw.slice(i + 1, end);
        const start = text.length;
        const p = parseInline(inner);
        text += p.text;
        italics.push([start, text.length]);
        for (const [s, e] of p.bolds) bolds.push([s + start, e + start]);
        for (const [s, e] of p.codes) codes.push([s + start, e + start]);
        i = end + 1;
        continue;
      }
    }
    text += raw[i];
    i++;
  }
  return { text, bolds, italics, codes };
}

// ---------- Block parser ----------
const lines = markdown.replace(/\r\n/g, '\n').split('\n');
const blocks = [];
let i = 0;
while (i < lines.length) {
  const line = lines[i];
  if (line.trim() === '') { i++; continue; }

  if (/^```/.test(line.trim())) {
    const codeLines = [];
    i++;
    while (i < lines.length && !/^```/.test(lines[i].trim())) { codeLines.push(lines[i]); i++; }
    i++;
    blocks.push({ type: 'code', raw: codeLines.join('\n') });
    continue;
  }
  if (/^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())) { blocks.push({ type: 'hr' }); i++; continue; }

  const headingMatch = line.match(/^(#{1,4})\s+(.*)$/);
  if (headingMatch) {
    blocks.push({ type: 'heading', level: headingMatch[1].length, raw: headingMatch[2].trim() });
    i++;
    continue;
  }
  if (/^>\s?/.test(line)) {
    const quoteLines = [];
    while (i < lines.length && /^>\s?/.test(lines[i])) { quoteLines.push(lines[i].replace(/^>\s?/, '')); i++; }
    blocks.push({ type: 'quote', lines: quoteLines });
    continue;
  }
  if (/^[-*]\s+/.test(line)) {
    const items = [];
    while (i < lines.length && /^[-*]\s+/.test(lines[i])) { items.push(lines[i].replace(/^[-*]\s+/, '')); i++; }
    blocks.push({ type: 'ul', items });
    continue;
  }
  if (/^\d+\.\s+/.test(line)) {
    const items = [];
    while (i < lines.length && /^\d+\.\s+/.test(lines[i])) { items.push(lines[i].replace(/^\d+\.\s+/, '')); i++; }
    blocks.push({ type: 'ol', items });
    continue;
  }
  if (/^\|/.test(line.trim())) {
    const tableLines = [];
    while (i < lines.length && lines[i].trim().startsWith('|')) { tableLines.push(lines[i]); i++; }
    const filtered = tableLines.filter(l => !/^\|?\s*:?-+:?\s*(\|\s*:?-+:?\s*)+\|?$/.test(l.trim()));
    blocks.push({ type: 'paragraph', raw: filtered.map(l => l.replace(/^\||\|$/g, '').split('|').map(c => c.trim()).join('   ')).join('\n') });
    continue;
  }
  const paraLines = [];
  while (
    i < lines.length && lines[i].trim() !== '' &&
    !/^```/.test(lines[i].trim()) && !/^(#{1,4})\s+/.test(lines[i]) &&
    !/^>\s?/.test(lines[i]) && !/^[-*]\s+/.test(lines[i]) &&
    !/^\d+\.\s+/.test(lines[i]) && !/^\|/.test(lines[i].trim()) &&
    !/^(-{3,}|\*{3,}|_{3,})$/.test(lines[i].trim())
  ) { paraLines.push(lines[i]); i++; }
  blocks.push({ type: 'paragraph', raw: paraLines.join(' ') });
}

// ---------- Assemble plain text + style ranges ----------
let text = '';
const paragraphStyles = [];
const textStyles = [];
const bulletRanges = [];

function appendParagraph(content, opts = {}) {
  const parsed = typeof content === 'string' ? parseInline(content) : content;
  const start = text.length;
  text += parsed.text;
  const end = text.length;
  text += '\n';
  if (opts.namedStyleType) paragraphStyles.push({ start, end: end + 1, namedStyleType: opts.namedStyleType });
  if (opts.indentStart) paragraphStyles.push({ start, end: end + 1, indentStart: opts.indentStart });
  for (const [s, e] of parsed.bolds) textStyles.push({ start: start + s, end: start + e, bold: true });
  for (const [s, e] of parsed.italics) textStyles.push({ start: start + s, end: start + e, italic: true });
  for (const [s, e] of parsed.codes) textStyles.push({ start: start + s, end: start + e, code: true });
}

for (const block of blocks) {
  if (block.type === 'heading') {
    const styleMap = { 1: 'HEADING_1', 2: 'HEADING_2', 3: 'HEADING_3', 4: 'HEADING_4' };
    appendParagraph(block.raw, { namedStyleType: styleMap[block.level] || 'HEADING_4' });
  } else if (block.type === 'paragraph') {
    appendParagraph(block.raw, { namedStyleType: 'NORMAL_TEXT' });
  } else if (block.type === 'quote') {
    for (const qLine of block.lines) {
      if (qLine.trim() === '') continue;
      appendParagraph(qLine, { namedStyleType: 'NORMAL_TEXT', indentStart: 36 });
    }
  } else if (block.type === 'code') {
    const start = text.length;
    text += block.raw;
    const end = text.length;
    text += '\n';
    paragraphStyles.push({ start, end: end + 1, namedStyleType: 'NORMAL_TEXT' });
    textStyles.push({ start, end, code: true });
  } else if (block.type === 'hr') {
    appendParagraph('─────────────────────────', { namedStyleType: 'NORMAL_TEXT' });
  } else if (block.type === 'ul') {
    const start = text.length;
    for (const item of block.items) appendParagraph(item, { namedStyleType: 'NORMAL_TEXT' });
    bulletRanges.push({ start, end: text.length, preset: 'BULLET_DISC_CIRCLE_SQUARE' });
  } else if (block.type === 'ol') {
    const start = text.length;
    for (const item of block.items) appendParagraph(item, { namedStyleType: 'NORMAL_TEXT' });
    bulletRanges.push({ start, end: text.length, preset: 'NUMBERED_DECIMAL_ALPHA_ROMAN' });
  }
}

// ---------- Build Google Docs API requests ----------
const requests = [];
const baseOffset = 1;

if (endIndex > 2) {
  requests.push({ deleteContentRange: { range: { startIndex: 1, endIndex: endIndex - 1 } } });
}
requests.push({ insertText: { location: { index: baseOffset }, text } });

for (const p of paragraphStyles) {
  const style = {};
  const fields = [];
  if (p.namedStyleType) { style.namedStyleType = p.namedStyleType; fields.push('namedStyleType'); }
  if (p.indentStart) { style.indentStart = { magnitude: p.indentStart, unit: 'PT' }; fields.push('indentStart'); }
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: baseOffset + p.start, endIndex: baseOffset + p.end },
      paragraphStyle: style,
      fields: fields.join(',')
    }
  });
}
for (const b of bulletRanges) {
  requests.push({
    createParagraphBullets: {
      range: { startIndex: baseOffset + b.start, endIndex: baseOffset + b.end },
      bulletPreset: b.preset
    }
  });
}
for (const t of textStyles) {
  if (t.start >= t.end) continue;
  const style = {};
  const fields = [];
  if (t.bold) { style.bold = true; fields.push('bold'); }
  if (t.italic) { style.italic = true; fields.push('italic'); }
  if (t.code) {
    style.weightedFontFamily = { fontFamily: 'Courier New' };
    style.backgroundColor = { color: { rgbColor: { red: 0.94, green: 0.94, blue: 0.94 } } };
    fields.push('weightedFontFamily', 'backgroundColor');
  }
  requests.push({
    updateTextStyle: {
      range: { startIndex: baseOffset + t.start, endIndex: baseOffset + t.end },
      textStyle: style,
      fields: fields.join(',')
    }
  });
}

return { json: { requests } };
